 const ambient=new THREE.HemisphereLight(0xfcfff4,0x7c8b61,3);scene.add(ambient);const sun=new THREE.DirectionalLight(0xfff8df,4);sun.position.set(-3,6,5);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-5;sun.shadow.camera.right=5;sun.shadow.camera.top=6;sun.shadow.camera.bottom=-5;sun.shadow.bias=-.001;scene.add(sun);const rim=new THREE.DirectionalLight(0xffffff,2);rim.position.set(4,2,-4);scene.add(rim);
