 const disk=mesh(new THREE.CylinderGeometry(2.42,2.5,.2,80),mat(0xf1f0de));disk.position.y=-2.13;const edge=mesh(new THREE.TorusGeometry(2.42,.012,8,80),mat(0xd4d8bd));edge.rotation.x=Math.PI/2;edge.position.y=-2.025;
