 const outline=mat(0x91b2a5,{transparent:true,opacity:.7,metalness:.15,roughness:.3});[-1.6,1.75].forEach(y=>{const ring=mesh(new THREE.TorusGeometry(.48,.016,12,64),outline,tube);ring.rotation.x=Math.PI/2;ring.position.y=y;ring.castShadow=false});
 const shine=mat(0xffffff,{transparent:true,opacity:.58,depthWrite:false});const stripe=mesh(new THREE.CylinderGeometry(.484,.484,3.12,32,1,true,.35,.07),shine,tube);stripe.position.y=.04;stripe.renderOrder=5;stripe.castShadow=false;
 const cork=mesh(new THREE.CylinderGeometry(.51,.465,.32,48),mat(0xb2965d,{roughness:1}),tube);cork.position.y=1.84;const corkTop=mesh(new THREE.CylinderGeometry(.512,.512,.035,48),mat(0xc1a571),tube);corkTop.position.y=2.01;
 const liquidMat=mat(colours.red,{roughness:.19,metalness:.08,emissive:colours.red,emissiveIntensity:.65,transparent:true,opacity:.94});const liquid=mesh(new THREE.CylinderGeometry(.443,.443,.61,64),liquidMat,tube);liquid.position.y=-1.285;const liquidBottom=mesh(new THREE.SphereGeometry(.443,48,24,0,Math.PI*2,Math.PI/2,Math.PI/2),liquidMat,tube);liquidBottom.position.y=-1.59;const liquidTop=mesh(new THREE.CircleGeometry(.443,64),mat(0xe78a9b,{roughness:.22}),tube);liquidTop.rotation.x=-Math.PI/2;liquidTop.position.y=-.975;
 const spec=new THREE.Group();tube.add(spec);let foil=null,worm=null,kind=null,foiled=null,lightLevel=70;let targetColour=new THREE.Color(colours.red);
 const lampGroup=new THREE.Group();lampGroup.position.set(1.43,-2.0,-.12);root.add(lampGroup);const lampMetal=mat(0x8c957b,{metalness:.55,roughness:.35});const lampBase=mesh(new THREE.CylinderGeometry(.48,.54,.12,48),mat(0x6e7c57),lampGroup);lampBase.position.y=.05;cylinder(new THREE.Vector3(0,.1,0),new THREE.Vector3(0,1.35,0),.055,lampMetal,lampGroup);cylinder(new THREE.Vector3(0,1.35,0),new THREE.Vector3(-.1,2.25,0),.055,lampMetal,lampGroup);const hinge=mesh(new THREE.SphereGeometry(.12,24,16),lampMetal,lampGroup);hinge.position.set(0,1.35,0);
 const head=new THREE.Group();head.position.set(-.1,2.25,0);head.rotation.z=-1.0;lampGroup.add(head);const shade=mesh(new THREE.CylinderGeometry(.16,.4,.42,40,1,true),mat(0x788561,{metalness:.22,side:THREE.DoubleSide}),head);const inner=mesh(new THREE.CircleGeometry(.37,40),mat(0xf5e5a6,{emissive:0xf3cc63,emissiveIntensity:.4}),head);inner.rotation.x=Math.PI/2;inner.position.y=-.2;const bulb=mesh(new THREE.SphereGeometry(.14,24,16),mat(0xffefbb,{emissive:0xffdb76,emissiveIntensity:1}),head);bulb.position.y=-.22;const bulbLight=new THREE.PointLight(0xffdf86,2,4);bulbLight.position.set(1.0,.0,0);root.add(bulbLight);
 const beams=new THREE.Group();root.add(beams);for(let i=0;i<4;i++){const b=cylinder(new THREE.Vector3(.95,.15+i*.04,.03),new THREE.Vector3(.3,.1+i*.19,.03),.007,mat(0xf0d17c,{transparent:true,opacity:.5}));root.remove(b);beams.add(b)}
 // A small reference tile on the workbench.
