 function clean(group){while(group.children.length){const child=group.children.pop();child.traverse(n=>{if(n.isMesh){n.geometry.dispose();if(n.material!==liquidMat)n.material.dispose()}});child.parent=null}}
 function build(c){clean(spec);foil=null;worm=null;const grey=mat(0x9da695,{metalness:.5,roughness:.4});if(['worm','soda'].includes(c.kind)){for(let i=-4;i<=4;i++){const off=i*.09,end=Math.sqrt(Math.max(0,.44*.44-off*off));cylinder(new THREE.Vector3(-end,-.02,off),new THREE.Vector3(end,-.02,off),.009,grey,spec);cylinder(new THREE.Vector3(off,-.015,-end),new THREE.Vector3(off,-.015,end),.009,grey,spec)}const r=mesh(new THREE.TorusGeometry(.445,.015,8,48),grey,spec);r.rotation.x=Math.PI/2;r.position.y=-.02;
 if(c.kind==='worm'){worm=new THREE.Group();spec.add(worm);worm.rotation.y=.1;for(let i=0;i<10;i++){const segment=mesh(new THREE.SphereGeometry(.085,20,14),mat(i===0?0x9e6331:i%2?0xc6944a:0xd8aa63),worm);segment.scale.set(.68,.78,.85);segment.position.set((i-4.5)*.066,.07+Math.sin(i*.5)*.018,Math.sin(i*.65)*.045);if(i<4){[-1,1].forEach(d=>cylinder(new THREE.Vector3((i-4.5)*.066,.035,0),new THREE.Vector3((i-4.5)*.066+.025,0,d*.115),.008,mat(0x8c6237),worm))}}}else{for(let i=0;i<21;i++){const angle=i*2.4,rad=.34*Math.sqrt((i+.5)/21);const grain=mesh(new THREE.DodecahedronGeometry(.062+(i%3)*.005,0),mat(i%2?0xd8d3b7:0xede9d0),spec);grain.position.set(Math.cos(angle)*rad,.06+(i%3)*.024,Math.sin(angle)*rad);grain.rotation.set(i,i*.2,i*.3)}}
 }else if(['leaf','variegated'].includes(c.kind)){cylinder(new THREE.Vector3(0,1.68,0),new THREE.Vector3(0,1.18,0),.008,mat(0xd2caa8),spec);const leafShape=new THREE.Shape();leafShape.moveTo(0,-.63);leafShape.bezierCurveTo(-.64,.02,-.39,.48,0,.64);leafShape.bezierCurveTo(.43,.39,.57,-.07,0,-.63);const leaf=mesh(new THREE.ShapeGeometry(leafShape,32),mat(0x71974a,{side:THREE.DoubleSide}),spec);leaf.position.y=.55;leaf.rotation.y=.28;leaf.scale.x=.85;const veinMat=mat(0xaec078);cylinder(new THREE.Vector3(0,-.06,.02),new THREE.Vector3(0,1.2,.02),.012,veinMat,spec);for(let j=0;j<4;j++){[-1,1].forEach(d=>cylinder(new THREE.Vector3(0,.17+j*.2,.025),new THREE.Vector3(d*(.23-j*.015),.38+j*.18,.025),.006,veinMat,spec))}if(c.kind==='variegated'){for(let i=0;i<6;i++){const patchShape=new THREE.Shape();patchShape.moveTo(0,0);patchShape.bezierCurveTo(.1,.03,.12,.16,.025,.22);patchShape.bezierCurveTo(-.06,.17,-.06,.05,0,0);const patch=mesh(new THREE.ShapeGeometry(patchShape),mat(0xf0edce,{side:THREE.DoubleSide}),spec);patch.position.set((i%2?1:-1)*(.085+(i%3)*.015),.13+Math.floor(i/2)*.26,.04);patch.rotation.z=i%2?-.25:.45;patch.scale.set(.9,1.2,1)}}
 if(c.foil){foil=new THREE.Group();spec.add(foil);const wrap=mesh(new THREE.CylinderGeometry(.515,.515,1.6,48,1,true),mat(0xc5ccc4,{metalness:.85,roughness:.32,side:THREE.DoubleSide}),foil);wrap.position.y=.48;for(let i=0;i<8;i++){const creas=mesh(new THREE.TorusGeometry(.519,.007,6,48),mat(i%2?0xd8ddd8:0x9ca89d,{metalness:.8,roughness:.4}),foil);creas.rotation.x=Math.PI/2;creas.rotation.z=.05*Math.sin(i);creas.position.y=-.23+i*.2}}
 }}
 let dragging=false,lastX=0,lastY=0,rotX=0,rotY=-.25;host.addEventListener('pointerdown',e=>{if(e.target.tagName!=='CANVAS')return;dragging=true;lastX=e.clientX;lastY=e.clientY;host.setPointerCapture(e.pointerId)});host.addEventListener('pointermove',e=>{if(!dragging)return;rotY+=(e.clientX-lastX)*.008;rotX=Math.max(-.15,Math.min(.25,rotX+(e.clientY-lastY)*.003));lastX=e.clientX;lastY=e.clientY});['pointerup','pointercancel'].forEach(ev=>host.addEventListener(ev,()=>dragging=false));host.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')rotY-=.15;if(e.key==='ArrowRight')rotY+=.15;if(e.key==='ArrowUp')rotX=Math.max(-.15,rotX-.05);if(e.key==='ArrowDown')rotX=Math.min(.25,rotX+.05)}});
 const resize=()=>{const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.position.set(4.4,2.6,camera.aspect<1?11.3:9.9);camera.lookAt(0,-.05,0);camera.updateProjectionMatrix()};new ResizeObserver(resize).observe(host);resize();let tick=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 renderer.setAnimationLoop(()=>{if(document.hidden)return;tick+=.012;root.rotation.y=THREE.MathUtils.lerp(root.rotation.y,rotY,.12);root.rotation.x=THREE.MathUtils.lerp(root.rotation.x,rotX,.12);liquidMat.color.lerp(targetColour,reduced?1:.035);liquidMat.emissive.copy(liquidMat.color);liquidTop.material.color.copy(liquidMat.color).lerp(new THREE.Color(0xffffff),.16);if(worm&&!reduced)worm.rotation.y=Math.sin(tick)*.025;renderer.render(scene,camera)});
 return{resetLiquid(){targetColour.set(colours.red);liquidMat.color.set(colours.red);liquidMat.emissive.set(colours.red);liquidTop.material.color.set(colours.red);},update(c,col,rebuild=true){targetColour.set(colours[col]);if(kind!==c.kind||foiled!==!!c.foil||rebuild){build(c);kind=c.kind;foiled=!!c.foil}lightLevel=c.light;beams.visible=c.light>0;bulb.material.emissiveIntensity=c.light/65;inner.material.emissiveIntensity=c.light/200;bulbLight.intensity=c.light/80},cutaway(open){if(foil)foil.visible=!open},reset(){rotY=-.25;rotX=0}};
